import { test, expect } from '@playwright/test';

test.describe('Example Table Functionality', () => {
  test('should display the correct number of rows and columns', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    const table = page.locator('#table1');
    const rows = await table.countByRole('row');
    const columns = await table.countByRole('column');
    expect(rows).toBeGreaterThan(0);
    expect(columns).toBeGreaterThan(0);
  });

  test('should contain the correct email in the table', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    const table = page.locator('#table1');
    const emailRow = await table.locator('[data-test="row-jsmith@gmail.com"]');
    await expect(emailRow).toBeVisible();
    await expect(emailRow).toHaveURL('https://the-internet.herokuapp.com/tables');
  });
});
